        costs = []
        for i in range(1, n + 1):
            row = list(map(int, lines[i].split()))
            costs.append(row)
        return n, costs

    def solve(self, n, costs):
        # Build adjacency matrix including diagonal
        adj = [[0] * n for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if i == j:
                    adj[i][j] = float('inf')
                else:
                    adj[i][j] = costs[i-1][j]

        matching = [-1] * n

        # Simple greedy matching try
        for i in range(n):
            if matching[i] == -1:
                best_j = -1
                best_cost = float('inf')
                for j in range(i + 1, n):
                    if matching[j] == -1:
                        if adj[i][j] < best_cost:
                            best_cost = adj[i][j]
                            best_j = j
                if best_j != -1:
                    matching[i] = best_j
                    matching[best_j] = i

        # Verify stability
        for i in range(n):
            for j in range(i + 1, n):
                curr_partner_i = matching[i]
                curr_cost_i = adj[i][curr_partner_i] if curr_partner_i != -1 else float('inf')

                if curr_partner_i != -1 and curr_partner_i != j:
                    # Check if i and j would both prefer to switch
                    curr_partner_j = matching[j]
                    if curr_partner_j != -1 and curr_partner_j != i:
                        cost_ij = adj[i][j]
                        if cost_ij < curr_cost_i and cost_ij < adj[j][curr_partner_j]:
                            return "-1"

        # Return matching
        result = [str(matching[i] + 1) for i in range(n)]
        return '\n'.join(result)

