    pos_map = [[] for _ in range(n + 1)]
    for i in range(n):
        pos_map[a[i]].append(i)

    # dp[j] = list of (position, cost) for all valid positions of b[j]
    dp = []

    # Base case: find first b[0]
    if not pos_map[b[0]]:
        return "NO"

    dp = []
    target = b[0]

    for pos in pos_map[target]:
        cost = sum(p[i] for i in range(pos) if a[i] >= b[0])
        dp.append((pos, cost))

    # For each subsequent b[j]
    for j in range(1, m):
        target = b[j]
        if not pos_map[target]:
            return "NO"

        new_dp = []
        prev_b = b[j-1]

        for curr_pos in pos_map[target]:
            best_cost = float('inf')

            for prev_pos, prev_cost in dp:
                if prev_pos >= curr_pos:
                    continue

                # Calculate additional cost between positions
                extra_cost = 0
                for k in range(prev_pos + 1, curr_pos):
                    if a[k] >= prev_b:
                        extra_cost += p[k]

                total_cost = prev_cost + extra_cost
                best_cost = min(best_cost, total_cost)

            if best_cost == float('inf'):
                return "NO"

            new_dp.append((curr_pos, best_cost))

        dp = new_dp

    # Handle final segment after b[m-1] - delete elements > b[m-1]
    last_pos, last_cost = min(dp, key=lambda x: x[1])

    for i in range(last_pos + 1, n):
        if a[i] > b[m-1]:
            last_cost += p[i]

    return "YES\n" + str(last_cost)

