import sys

def count_factors(num: int) -> Tuple[int, int]:
    """Count factors of 2 and 5 in num."""
    if num == 0:
        return (float('inf'), float('inf'))  # 0 contributes infinite factors
    cnt2 = 0
    cnt5 = 0
    while num > 0 and num % 2 == 0:
        cnt2 += 1
        num //= 2
    while num > 0 and num % 5 == 0:
        cnt5 += 1
        num //= 5
    return (cnt2, cnt5)

def count_trailing_zeros(f2: int, f5: int) -> int:
    """Calculate trailing zeros from factor counts."""
    return min(f2, f5)

def parse_input(input_str: str) -> Tuple[int, List[List[int]]]:
    lines = input_str.strip().split('\n')
    n = int(lines[0])
    matrix = []
    for i in range(1, n + 1):
        row = [int(x) for x in lines[i].split()]
        matrix.append(row)
    return n, matrix

def solve(n: int, matrix: List[List[int]]) -> Tuple[int, str]:
    # dp[i][j] = list of (cnt2, cnt5) pairs that are non-dominated
    # A pair A is non-dominated if there's no other reachable pair B
    # where cnt2_B <= cnt2_A and cnt5_B <= cnt5_A and at least one is strictly less

    # Using 2D array storing list of factor pairs
    dp = [[[] for _ in range(n)] for _ in range(n)]

    # Precompute factor counts for each cell
    factors = [[count_factors(matrix[i][j]) for j in range(n)] for i in range(n)]

    # Initialize starting cell
    dp[0][0].append(factors[0][0])

    # Fill DP table
    for i in range(n):
        for j in range(n):
            if i == 0 and j == 0:
                continue

            # Get all reachable pairs from top or left
            candidates = dp[i-1][j] if i > 0 else []
            if j > 0:
                candidates2 = dp[i][j-1]
                candidates.extend(candidates2)

            if not candidates:
                continue

            # Compute new pairs for current cell
            f2_all, f5_all = factors[i][j]
            if f2_all == float('inf') and f5_all == float('inf'):
                # Zero case
                new_pairs = [(float('inf'), float('inf'))]
            else:
                new_pairs = []
                for (c2, c5) in candidates:
                    if c2 == float('inf') or c5 == float('inf'):
                        new_pairs.append((float('inf'), float('inf')))
                    else:
                        new_pairs.append((c2 + f2_all, c5 + f5_all))

            # Remove dominated pairs
            result = []
            result.append(new_pairs[0])
            for (c2_new, c5_new) in new_pairs[1:]:
                dominated = False
                for (c2_old, c5_old) in result:
                    if c2_old <= c2_new and c5_old <= c5_new:
                        dominated = True
                        break
                if not dominated:
                    result.append((c2_new, c5_new))
            dp[i][j] = result

    # Find minimum trailing zeros at destination
    final_pairs = dp[n-1][n-1]

    # Parse back to reconstruct path
    # For each cell, keep track of which predecessor gave each non-dominated pair

    # We'll rebuild this information when tracing back
    min_zeros = float('inf')
    best_pair = None

    for (c2, c5) in final_pairs:
        zeros = count_trailing_zeros(c2, c5)
        if zeros < min_zeros:
            min_zeros = zeros
            best_pair = (c2, c5)
        elif zeros == min_zeros:
            if (c2, c5) < (best_pair[0], best_pair[1]):
                best_pair = (c2, c5)

    # Reconstruct path by backtracking
    path = []
    i, j = n - 1, n - 1

    while i > 0 or j > 0:
        current = factors[i][j]
        if current == (float('inf'), float('inf')):
            current2 = (float('inf'), float('inf'))
        else:
            current2 = current

        target_before = (best_pair[0] - current2[0], best_pair[1] - current2[1])
        target_before = (float('inf') if target_before[0] % 1 != 0 else target_before[0 if target_before[0] >= 0 else -target_before[0]], 
                         float('inf') if target_before[1] % 1 != 0 else target_before[1])

        found = False
        if i > 0:
            for (c2_prev, c5_prev) in dp[i-1][j]:
                if abs(c2_prev - target_before[0]) < 1e-9 and abs(c5_prev - target_before[1]) < 1e-9:
                    path.append('U')  # Coming from top, so move up in reconstruction
                    i -= 1
                    found = True
                    break

        if not found and j > 0:
            for (c2_prev, c5_prev) in dp[i][j-1]:
                if abs(c2_prev - target_before[0]) < 1e-9 and abs(c5_prev - target_before[1]) < 1e-9:
                    path.append('L')
                    j -= 1
                    found = True
                    break

        if not found:
            # Try both possible paths
            candidates = []
            if i > 0:
                candidates.append((i-1, j, 'U', None))
            if j > 0:
                candidates.append((i, j-1, 'L', None))

            best_move = None
            for (prev_i, prev_j, move, _) in candidates:
                for (c2_prev, c5_prev) in dp[prev_i][prev_j]:
                    new_zeros = count_trailing_zeros(best_pair[0] - (factors[i][j][0] - factors[prev_i][prev_j][0]) if i > 0 and prev_i >= 0 else float('inf'),
                                                   best_pair[1] - (factors[i][j][1] - factors[prev_i][prev_j][1]) if j > 0 and prev_j >= 0 else float('inf'))
                    # Simplified: just find first valid path
                    if abs(best_pair[0] - (c2_prev + factors[i][j][0])) < 1e-9 and abs(best_pair[1] - (c5_prev + factors[i][j][1])) < 1e-9:
                        best_move = (prev_i, prev_j, move)
                        break
                if best_move:
                    break

            if best_move:
                i, j, path.append(best_move[2])
                continue

    path.reverse()
    path = ''.join(path)

    if min_zeros == float('inf'):
        min_zeros = 0

    return (min_zeros, path)

def solution(input_str: str) -> str:
    n, matrix = parse_input(input_str)
    zeros, path = solve(n, matrix)
    return f"{zeros}\n{path}"

