    class FenwickTree:
        def __init__(self, size):
            self.tree = [0] * (size + 1)

        def update(self, i, delta):
            while i < len(self.tree):
                self.tree[i] += delta
                i += i & (-i)

        def query(self, i):
            s = 0
            while i > 0:
                s += self.tree[i]
                i -= i & (-i)
            return s

        def query_range(self, l, r):
