    if k == 1:
        return str(n % MOD)

    # Memoization: state = (last_pos, count, visited_mask)
    # visited_mask uses n bits, where k bits will be set
    memo = {}

    def count_ways(last_pos, count, visited_mask):
        # Return 1 when we've visited k planets
        if count == k:
            return 1

        state = (last_pos, count, visited_mask)
        if state in memo:
            return memo[state]

        result = 0
        # Try all possible next positions
        for next_pos in range(1, n + 1):
            # Check if unvisited and within reach
            if not (visited_mask & (1 << (next_pos - 1))) and next_pos <= last_pos + m:
                new_mask = visited_mask | (1 << (next_pos - 1))
                result = (result + count_ways(next_pos, count + 1, new_mask)) % MOD

        memo[state] = result
        return result

    # Sum over all possible starting positions
    ans = 0
    MOD = 10**9 + 7
    for start_pos in range(1, n + 1):
        ans = (ans + count_ways(start_pos, 1, 1 << (start_pos - 1))) % MOD

    return str(ans)

